import { redirect } from "next/navigation";

import { API_INTERNAL_URL } from "@/lib/api/internal-url";
import { getSessionToken } from "@/lib/auth/session";

/** Opened by a link: a short sentence in place of the file, never details. */
function failure(message: string, status: number) {
    return new Response(message, {
        status,
        headers: {
            "Content-Type": "text/plain; charset=utf-8",
            "X-Content-Type-Options": "nosniff",
        },
    });
}

/**
 * The summary of a submitted diagnostic as a PDF (US-07), generated by the
 * API with the session token. The API only serves the diagnostics of the
 * same organization (404 otherwise) and names the file.
 */
export async function GET(
    _request: Request,
    { params }: RouteContext<"/diagnostic-files/[id]">,
) {
    const { id } = await params;
    const token = await getSessionToken();
    if (!token) redirect("/login?next=/diagnostic/historique");

    if (!/^\d+$/.test(id)) {
        return failure("Ce diagnostic n'existe pas.", 404);
    }

    let response: Response;
    try {
        response = await fetch(
            `${API_INTERNAL_URL}/api/diagnostics/${id}/pdf`,
            {
                headers: { Authorization: `Bearer ${token}` },
                cache: "no-store",
            },
        );
    } catch {
        return failure(
            "La synthèse est indisponible pour le moment. Réessayez dans un instant.",
            503,
        );
    }

    if (response.status === 401) redirect("/session-expired");
    if (response.status === 404 || !response.body) {
        return failure("Ce diagnostic n'existe pas.", 404);
    }
    if (!response.ok) {
        return failure(
            "La synthèse est indisponible pour le moment. Réessayez dans un instant.",
            503,
        );
    }

    const headers = new Headers({
        "Cache-Control": "private, no-store",
        "X-Content-Type-Options": "nosniff",
    });
    for (const name of [
        "Content-Type",
        "Content-Length",
        "Content-Disposition",
        "Content-Security-Policy",
    ]) {
        const value = response.headers.get(name);
        if (value) headers.set(name, value);
    }

    return new Response(response.body, { headers });
}
